@Test
public void testFillNoHighSurrogate() throws IOException {
    CharacterUtils[] versions = new CharacterUtils[] { CharacterUtils.getInstance(), CharacterUtils.getJava4Instance() };
    for (CharacterUtils instance : versions) {
        Reader reader = new StringReader("helloworld");
        CharacterBuffer buffer = CharacterUtils.newCharacterBuffer(6);
        assertTrue(instance.fill(buffer, reader));
        assertEquals(0, buffer.getOffset());
        assertEquals(6, buffer.getLength());
        assertEquals("hellow", new String(buffer.getBuffer()));
        assertFalse(instance.fill(buffer, reader));
        assertEquals(4, buffer.getLength());
        assertEquals(0, buffer.getOffset());
        assertEquals("orld", new String(buffer.getBuffer(), buffer.getOffset(), buffer.getLength()));
        assertFalse(instance.fill(buffer, reader));
    }
}

@Test
public void testFillJava15() throws IOException {
    String input = "1234\ud801\udc1c789123\ud801\ud801\udc1c\ud801";
    CharacterUtils instance = CharacterUtils.getInstance();
    Reader reader = new StringReader(input);
    CharacterBuffer buffer = CharacterUtils.newCharacterBuffer(5);
    assertTrue(instance.fill(buffer, reader));
    assertEquals(4, buffer.getLength());
    assertEquals("1234", new String(buffer.getBuffer(), buffer.getOffset(), buffer.getLength()));
    assertTrue(instance.fill(buffer, reader));
    assertEquals(5, buffer.getLength());
    assertEquals("\ud801\udc1c789", new String(buffer.getBuffer()));
    assertTrue(instance.fill(buffer, reader));
    assertEquals(4, buffer.getLength());
    assertEquals("123\ud801", new String(buffer.getBuffer(), buffer.getOffset(), buffer.getLength()));
    assertFalse(instance.fill(buffer, reader));
    assertEquals(3, buffer.getLength());
    assertEquals("\ud801\udc1c\ud801", new String(buffer.getBuffer(), buffer.getOffset(), buffer.getLength()));
    assertFalse(instance.fill(buffer, reader));
    assertEquals(0, buffer.getLength());
}

@Test
public void testFillJava14() throws IOException {
    String input = "1234\ud801\udc1c789123\ud801\ud801\udc1c\ud801";
    CharacterUtils instance = CharacterUtils.getJava4Instance();
    Reader reader = new StringReader(input);
    CharacterBuffer buffer = CharacterUtils.newCharacterBuffer(5);
    assertTrue(instance.fill(buffer, reader));
    assertEquals(5, buffer.getLength());
    assertEquals("1234\ud801", new String(buffer.getBuffer(), buffer.getOffset(), buffer.getLength()));
    assertTrue(instance.fill(buffer, reader));
    assertEquals(5, buffer.getLength());
    assertEquals("\udc1c7891", new String(buffer.getBuffer()));
    buffer = CharacterUtils.newCharacterBuffer(6);
    assertTrue(instance.fill(buffer, reader));
    assertEquals(6, buffer.getLength());
    assertEquals("23\ud801\ud801\udc1c\ud801", new String(buffer.getBuffer(), buffer.getOffset(), buffer.getLength()));
    assertFalse(instance.fill(buffer, reader));
}

@Test
public void testLookup() throws IOException {
    UserDictionary dictionary = TestJapaneseTokenizer.readDict();
    String s = "関西国際空港に行った";
    int[][] dictionaryEntryResult = dictionary.lookup(s.toCharArray(), 0, s.length());
    // Length should be three 関西, 国際, 空港
    assertEquals(3, dictionaryEntryResult.length);
    // Test positions
    // index of 関西
    assertEquals(0, dictionaryEntryResult[0][1]);
    // index of 国際
    assertEquals(2, dictionaryEntryResult[1][1]);
    // index of 空港
    assertEquals(4, dictionaryEntryResult[2][1]);
    // Test lengths
    // length of 関西
    assertEquals(2, dictionaryEntryResult[0][2]);
    // length of 国際
    assertEquals(2, dictionaryEntryResult[1][2]);
    // length of 空港
    assertEquals(2, dictionaryEntryResult[2][2]);
    s = "関西国際空港と関西国際空港に行った";
    int[][] dictionaryEntryResult2 = dictionary.lookup(s.toCharArray(), 0, s.length());
    // Length should be six
    assertEquals(6, dictionaryEntryResult2.length);
}

@Test
public void testReadings() throws IOException {
    UserDictionary dictionary = TestJapaneseTokenizer.readDict();
    int[][] result = dictionary.lookup("日本経済新聞".toCharArray(), 0, 6);
    assertEquals(3, result.length);
    // wordId of 日本 in 日本経済新聞
    int wordIdNihon = result[0][0];
    assertEquals("ニホン", dictionary.getReading(wordIdNihon, "日本".toCharArray(), 0, 2));
    result = dictionary.lookup("朝青龍".toCharArray(), 0, 3);
    assertEquals(1, result.length);
    // wordId for 朝青龍
    int wordIdAsashoryu = result[0][0];
    assertEquals("アサショウリュウ", dictionary.getReading(wordIdAsashoryu, "朝青龍".toCharArray(), 0, 3));
}

