    for (LeafReaderContext context : reader.leaves()) {
        LeafReader r = context.reader();
        NumericDocValues ndv = r.getNumericDocValues("val");
        assertNotNull(ndv);
        for (int i = 0; i < r.maxDoc(); i++) {
