    HashSet<byte[]> set = new HashSet<>();
    byte[] block = allocator.getByteBlock();
    set.add(block);
    assertNotNull(block);
    final int size = block.length;
    int num = atLeast(97);
    for (int i = 0; i < num; i++) {
        block = allocator.getByteBlock();
        assertNotNull(block);
