    final ParallelTaxonomyArrays ca2 = trBase.getParallelTaxonomyArrays();
    final int abYoungChildBase2 = ca2.children()[abOrd];
    int numRetries = atLeast(50);
    for (int retry = 0; retry < numRetries; retry++) {
