@Test
public void testAbuseOfSort() {
    assertU(adoc("id", "9999991", "sortabuse_b", "true", "sortabuse_t", "zzz xxx ccc vvv bbb nnn aaa sss ddd fff ggg"));
    assertU(adoc("id", "9999992", "sortabuse_b", "true", "sortabuse_t", "zzz xxx ccc vvv bbb nnn qqq www eee rrr ttt"));
    assertU(commit());
    try {
        ignoreException("can not sort on multivalued field: sortabuse_t");
        assertQ("sort on something that shouldn't work", req("q", "sortabuse_b:true", "sort", "sortabuse_t asc"), "*[count(//doc)=2]");
        fail("no error encountered when sorting on sortabuse_t");
    } catch (Exception outer) {
        // EXPECTED
        Throwable root = getRootCause(outer);
