        assertEquals("incorrect error type", SolrException.ErrorCode.BAD_REQUEST, SolrException.ErrorCode.getErrorCode(e.code()));
        assertTrue("exception doesn't contain field name", -1 != e.getMessage().indexOf("sortabuse_t"));
    }
}

