@Test
public void stressTest() throws Exception {
    final CachingDirectoryFactory df = new RAMDirectoryFactory();
    List<Thread> threads = new ArrayList<>();
    int threadCount = 11;
    for (int i = 0; i < threadCount; i++) {
        Thread getDirThread = new GetDirThread(df);
        threads.add(getDirThread);
        getDirThread.start();
    }
    for (int i = 0; i < 4; i++) {
        Thread releaseDirThread = new ReleaseDirThread(df);
        threads.add(releaseDirThread);
        releaseDirThread.start();
    }
    for (int i = 0; i < 2; i++) {
        Thread incRefThread = new IncRefThread(df);
        threads.add(incRefThread);
        incRefThread.start();
    }
    Thread.sleep(TEST_NIGHTLY ? 30000 : 8000);
    Thread closeThread = new Thread() {

        public void run() {
            try {
                df.close();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
    };
    closeThread.start();
    stop = true;
    for (Thread thread : threads) {
        thread.join();
    }
    // do any remaining releases
    synchronized (dirs) {
        int sz = dirs.size();
        if (sz > 0) {
            for (Tracker tracker : dirs.values()) {
                int cnt = tracker.refCnt.get();
                for (int i = 0; i < cnt; i++) {
                    tracker.refCnt.decrementAndGet();
                    df.release(tracker.dir);
                }
            }
        }
    }
    closeThread.join();
}

@Test
public void testPrefixQuery() throws Exception {
    String q = "name:a*";
    assertJQ(req("q", q, "timeAllowed", "1", "sleep", sleep), failureAssertionString);
    // do the same query and test for both success, and that the number of documents matched (i.e. make sure no partial results were cached)
    assertJQ(req("q", q, "timeAllowed", longTimeout), assertionString);
    // this time we should get a query cache hit and hopefully no exception?  this may change in the future if time checks are put into other places.
    assertJQ(req("q", q, "timeAllowed", "1", "sleep", sleep), assertionString);
    // now do the same for the filter cache
    assertJQ(req("q", "*:*", "fq", q, "timeAllowed", "1", "sleep", sleep), failureAssertionString);
    // make sure that the result succeeds this time, and that a bad filter wasn't cached
    assertJQ(req("q", "*:*", "fq", q, "timeAllowed", longTimeout), assertionString);
    // test that Long.MAX_VALUE works
    assertJQ(req("q", "name:b*", "timeAllowed", Long.toString(Long.MAX_VALUE)), assertionString);
    // negative timeAllowed should disable timeouts.
    assertJQ(req("q", "name:c*", "timeAllowed", "-7"), assertionString);
}

// There are lots of assumptions about how/when cache entries should be changed in this method. The
// simple case above shows the root problem without the confusion. testFilterSimpleCase should be
// removed once it is running and this test should be un-ignored and the assumptiions verified.
// With all the weirdness, I'm not going to vouch for this test. Feel free to change it.
@Test
public void testCacheAssumptions() throws Exception {
    String fq = "name:d*";
    SolrCore core = h.getCore();
    SolrInfoMBean filterCacheStats = core.getInfoRegistry().get("filterCache");
    long fqInserts = (long) filterCacheStats.getStatistics().get("inserts");
    SolrInfoMBean queryCacheStats = core.getInfoRegistry().get("queryResultCache");
    long qrInserts = (long) queryCacheStats.getStatistics().get("inserts");
    // This gets 0 docs back. Use 10000 instead of 1 for timeAllowed and it gets 100 back and the for loop below
    // succeeds.
    String response = JQ(req("q", "*:*", "fq", fq, "indent", "true", "timeAllowed", "1", "sleep", sleep));
    Map res = (Map) ObjectBuilder.fromJSON(response);
    Map body = (Map) (res.get("response"));
    assertTrue("Should have fewer docs than " + NUM_DOCS, (long) (body.get("numFound")) < NUM_DOCS);
    Map header = (Map) (res.get("responseHeader"));
    assertTrue("Should have partial results", (Boolean) (header.get("partialResults")));
    assertEquals("Should NOT have inserted partial results in the cache!", (long) queryCacheStats.getStatistics().get("inserts"), qrInserts);
    assertEquals("Should NOT have another insert", fqInserts, (long) filterCacheStats.getStatistics().get("inserts"));
    // At the end of all this, we should have no hits in the queryResultCache.
    response = JQ(req("q", "*:*", "fq", fq, "indent", "true", "timeAllowed", longTimeout));
    // Check that we did insert this one.
    assertEquals("Hits should still be 0", (long) filterCacheStats.getStatistics().get("hits"), 0L);
    assertEquals("Inserts should be bumped", (long) filterCacheStats.getStatistics().get("inserts"), fqInserts + 1);
    res = (Map) ObjectBuilder.fromJSON(response);
    body = (Map) (res.get("response"));
    assertEquals("Should have exactly " + NUM_DOCS, (long) (body.get("numFound")), NUM_DOCS);
    header = (Map) (res.get("responseHeader"));
    assertTrue("Should NOT have partial results", header.get("partialResults") == null);
}

// When looking at a problem raised on the user's list I ran across this anomaly with timeAllowed
// This tests for the second query NOT returning partial results, along with some other
@Test
public void testQueryResults() throws Exception {
    String q = "name:e*";
    SolrCore core = h.getCore();
    SolrInfoMBean queryCacheStats = core.getInfoRegistry().get("queryResultCache");
    NamedList nl = queryCacheStats.getStatistics();
    long inserts = (long) nl.get("inserts");
    String response = JQ(req("q", q, "indent", "true", "timeAllowed", "1", "sleep", sleep));
    // The queryResultCache should NOT get an entry here.
    nl = queryCacheStats.getStatistics();
    assertEquals("Should NOT have inserted partial results!", inserts, (long) nl.get("inserts"));
    Map res = (Map) ObjectBuilder.fromJSON(response);
    Map body = (Map) (res.get("response"));
    Map header = (Map) (res.get("responseHeader"));
    assertTrue("Should have fewer docs than " + NUM_DOCS, (long) (body.get("numFound")) < NUM_DOCS);
    assertTrue("Should have partial results", (Boolean) (header.get("partialResults")));
    response = JQ(req("q", q, "indent", "true", "timeAllowed", longTimeout));
    // Check that we did insert this one.
    NamedList nl2 = queryCacheStats.getStatistics();
    assertEquals("Hits should still be 0", (long) nl.get("hits"), (long) nl2.get("hits"));
    assertTrue("Inserts should be bumped", inserts < (long) nl2.get("inserts"));
    res = (Map) ObjectBuilder.fromJSON(response);
    body = (Map) (res.get("response"));
    header = (Map) (res.get("responseHeader"));
    assertEquals("Should have exactly " + NUM_DOCS, NUM_DOCS, (long) (body.get("numFound")));
    Boolean test = (Boolean) (header.get("partialResults"));
    if (test != null) {
        assertFalse("Should NOT have partial results", test);
    }
}

@Test
public void testInitArgsOrSysPropConfig() throws Exception {
    HdfsDirectoryFactory hdfsFactory = new HdfsDirectoryFactory();
    // test sys prop config
    System.setProperty("solr.hdfs.home", HdfsTestUtil.getURI(dfsCluster) + "/solr1");
    hdfsFactory.init(new NamedList<>());
    String dataHome = hdfsFactory.getDataHome(new MockCoreDescriptor());
    assertTrue(dataHome.endsWith("/solr1/mock/data"));
    System.clearProperty("solr.hdfs.home");
    // test init args config
    NamedList<Object> nl = new NamedList<>();
    nl.add("solr.hdfs.home", HdfsTestUtil.getURI(dfsCluster) + "/solr2");
    hdfsFactory.init(nl);
    dataHome = hdfsFactory.getDataHome(new MockCoreDescriptor());
    assertTrue(dataHome.endsWith("/solr2/mock/data"));
    // test sys prop and init args config - init args wins
    System.setProperty("solr.hdfs.home", HdfsTestUtil.getURI(dfsCluster) + "/solr1");
    hdfsFactory.init(nl);
    dataHome = hdfsFactory.getDataHome(new MockCoreDescriptor());
    assertTrue(dataHome.endsWith("/solr2/mock/data"));
    System.clearProperty("solr.hdfs.home");
    // set conf dir by sys prop
    Path confDir = createTempDir();
    System.setProperty(HdfsDirectoryFactory.CONFIG_DIRECTORY, confDir.toString());
    Directory dir = hdfsFactory.create(HdfsTestUtil.getURI(dfsCluster) + "/solr", NoLockFactory.INSTANCE, DirContext.DEFAULT);
    try {
        assertEquals(confDir.toString(), hdfsFactory.getConfDir());
    } finally {
        dir.close();
    }
    // check bool and int getConf impls
    nl = new NamedList<>();
    nl.add(HdfsDirectoryFactory.NRTCACHINGDIRECTORY_MAXMERGESIZEMB, 4);
    System.setProperty(HdfsDirectoryFactory.NRTCACHINGDIRECTORY_MAXMERGESIZEMB, "3");
    nl.add(HdfsDirectoryFactory.BLOCKCACHE_ENABLED, true);
    System.setProperty(HdfsDirectoryFactory.BLOCKCACHE_ENABLED, "false");
    hdfsFactory.init(nl);
    assertEquals(4, hdfsFactory.getConfig(HdfsDirectoryFactory.NRTCACHINGDIRECTORY_MAXMERGESIZEMB, 0));
    assertEquals(true, hdfsFactory.getConfig(HdfsDirectoryFactory.BLOCKCACHE_ENABLED, false));
    nl = new NamedList<>();
    hdfsFactory.init(nl);
    System.setProperty(HdfsDirectoryFactory.BLOCKCACHE_ENABLED, "true");
    assertEquals(3, hdfsFactory.getConfig(HdfsDirectoryFactory.NRTCACHINGDIRECTORY_MAXMERGESIZEMB, 0));
    assertEquals(true, hdfsFactory.getConfig(HdfsDirectoryFactory.BLOCKCACHE_ENABLED, false));
    System.clearProperty(HdfsDirectoryFactory.NRTCACHINGDIRECTORY_MAXMERGESIZEMB);
    System.clearProperty(HdfsDirectoryFactory.BLOCKCACHE_ENABLED);
    assertEquals(0, hdfsFactory.getConfig(HdfsDirectoryFactory.NRTCACHINGDIRECTORY_MAXMERGESIZEMB, 0));
    assertEquals(false, hdfsFactory.getConfig(HdfsDirectoryFactory.BLOCKCACHE_ENABLED, false));
    hdfsFactory.close();
}

@Test
public void testCleanupOldIndexDirectories() throws Exception {
    HdfsDirectoryFactory hdfsFactory = new HdfsDirectoryFactory();
    System.setProperty("solr.hdfs.home", HdfsTestUtil.getURI(dfsCluster) + "/solr1");
    hdfsFactory.init(new NamedList<>());
    String dataHome = hdfsFactory.getDataHome(new MockCoreDescriptor());
    assertTrue(dataHome.endsWith("/solr1/mock/data"));
    System.clearProperty("solr.hdfs.home");
    FileSystem hdfs = dfsCluster.getFileSystem();
    org.apache.hadoop.fs.Path dataHomePath = new org.apache.hadoop.fs.Path(dataHome);
    org.apache.hadoop.fs.Path currentIndexDirPath = new org.apache.hadoop.fs.Path(dataHomePath, "index");
    assertTrue(!hdfs.isDirectory(currentIndexDirPath));
    hdfs.mkdirs(currentIndexDirPath);
    assertTrue(hdfs.isDirectory(currentIndexDirPath));
    String timestamp1 = new SimpleDateFormat(SnapShooter.DATE_FMT, Locale.ROOT).format(new Date());
    org.apache.hadoop.fs.Path oldIndexDirPath = new org.apache.hadoop.fs.Path(dataHomePath, "index." + timestamp1);
    assertTrue(!hdfs.isDirectory(oldIndexDirPath));
    hdfs.mkdirs(oldIndexDirPath);
    assertTrue(hdfs.isDirectory(oldIndexDirPath));
    hdfsFactory.cleanupOldIndexDirectories(dataHomePath.toString(), currentIndexDirPath.toString());
    assertTrue(hdfs.isDirectory(currentIndexDirPath));
    assertTrue(!hdfs.isDirectory(oldIndexDirPath));
}

