    clearIndex();
    assertU(adoc("id", "M1"));
    assertU(adoc(getDoc("+4", 4, "2011-04-04T00:00:00Z")));
    assertU(adoc(getDoc("+5", 5, "2011-05-05T00:00:00Z")));
    assertU(adoc(getDoc("-3", -3, "2011-01-01T00:00:00Z")));
    assertU(adoc("id", "M2"));
