    // default to reading pt first
    assertJQ(req("defType", "func", "q", "geodist(1,2)", "pt", "3,4", "sfield", "store", "fq", "id:100", "fl", "id,score"), 1e-5, "/response/docs/[0]/score==314.40338");
    // if pt missing, use sfield
    assertJQ(req("defType", "func", "q", "geodist(3,4)", "sfield", "store", "fq", "id:100", "fl", "id,score"), 1e-5, "/response/docs/[0]/score==314.40338");
