@Test
public void testDefaultField() {
    assertU(adoc("text", "john smith", "id", "1"));
    assertU(adoc("text", "johathon smith", "id", "2"));
    assertU(adoc("text", "john percival smith", "id", "3"));
    assertU(commit());
    assertU(optimize());
    assertQ(req("q", "{!complexphrase} \"john smith\""), "//result[@numFound='1']", "//doc[./str[@name='id']='1']");
    assertQ(req("q", "{!complexphrase} \"j* smyth~\""), "//result[@numFound='2']", "//doc[./str[@name='id']='1']", "//doc[./str[@name='id']='2']");
    assertQ(req("q", "{!complexphrase} \"(jo* -john) smith\""), "//result[@numFound='1']", "//doc[./str[@name='id']='2']");
    assertQ(req("q", "{!complexphrase} \"jo* smith\"~2"), "//result[@numFound='3']", "//doc[./str[@name='id']='1']", "//doc[./str[@name='id']='2']", "//doc[./str[@name='id']='3']");
