    String id1 = "dorothy";
    assertU(adoc("id", id1));
    String id2 = "kansas";
    assertU(adoc("id", id2));
    assertU(commit());
    assertJQ(req("q", "*:*"), "/response/numFound==2");
    List<DocRouter.Range> ranges = getRanges(id1, id2);
    SolrCore core1 = null, core2 = null;
    try {
        String instanceDir = h.getCore().getCoreDescriptor().getInstanceDir();
        CoreDescriptor dcore1 = buildCoreDescriptor(h.getCoreContainer(), "split1", instanceDir).withDataDir(indexDir1.getAbsolutePath()).withSchema("schema12.xml").build();
        core1 = h.getCoreContainer().create(dcore1);
        CoreDescriptor dcore2 = buildCoreDescriptor(h.getCoreContainer(), "split2", instanceDir).withDataDir(indexDir2.getAbsolutePath()).withSchema("schema12.xml").build();
        core2 = h.getCoreContainer().create(dcore2);
        LocalSolrQueryRequest request = null;
        try {
            request = lrf.makeRequest("q", "dummy");
            SplitIndexCommand command = new SplitIndexCommand(request, null, Lists.newArrayList(core1, core2), ranges, new PlainIdRouter(), null, null);
            new SolrIndexSplitter(command).split();
        } finally {
            if (request != null)
                request.close();
        }
        EmbeddedSolrServer server1 = new EmbeddedSolrServer(h.getCoreContainer(), "split1");
        EmbeddedSolrServer server2 = new EmbeddedSolrServer(h.getCoreContainer(), "split2");
        server1.commit(true, true);
        server2.commit(true, true);
        assertEquals("id:dorothy should be present in split index1", 1, server1.query(new SolrQuery("id:dorothy")).getResults().getNumFound());
        assertEquals("id:kansas should not be present in split index1", 0, server1.query(new SolrQuery("id:kansas")).getResults().getNumFound());
        assertEquals("id:dorothy should not be present in split index2", 0, server2.query(new SolrQuery("id:dorothy")).getResults().getNumFound());
        assertEquals("id:kansas should be present in split index2", 1, server2.query(new SolrQuery("id:kansas")).getResults().getNumFound());
    } finally {
        h.getCoreContainer().unload("split2");
        h.getCoreContainer().unload("split1");
    }
}

@Test
public void testSplitAlternately() throws Exception {
    LocalSolrQueryRequest request = null;
    Directory directory = null;
    try {
        // add an even number of docs
        int max = (1 + random().nextInt(10)) * 3;
        log.info("Adding {} number of documents", max);
        for (int i = 0; i < max; i++) {
            assertU(adoc("id", String.valueOf(i)));
        }
        assertU(commit());
        request = lrf.makeRequest("q", "dummy");
        SplitIndexCommand command = new SplitIndexCommand(request, Lists.newArrayList(indexDir1.getAbsolutePath(), indexDir2.getAbsolutePath(), indexDir3.getAbsolutePath()), null, null, new PlainIdRouter(), null, null);
        new SolrIndexSplitter(command).split();
        directory = h.getCore().getDirectoryFactory().get(indexDir1.getAbsolutePath(), DirectoryFactory.DirContext.DEFAULT, h.getCore().getSolrConfig().indexConfig.lockType);
        DirectoryReader reader = DirectoryReader.open(directory);
        assertEquals("split index1 has wrong number of documents", max / 3, reader.numDocs());
        reader.close();
        h.getCore().getDirectoryFactory().release(directory);
        directory = h.getCore().getDirectoryFactory().get(indexDir2.getAbsolutePath(), DirectoryFactory.DirContext.DEFAULT, h.getCore().getSolrConfig().indexConfig.lockType);
        reader = DirectoryReader.open(directory);
        assertEquals("split index2 has wrong number of documents", max / 3, reader.numDocs());
        reader.close();
        h.getCore().getDirectoryFactory().release(directory);
        directory = h.getCore().getDirectoryFactory().get(indexDir3.getAbsolutePath(), DirectoryFactory.DirContext.DEFAULT, h.getCore().getSolrConfig().indexConfig.lockType);
        reader = DirectoryReader.open(directory);
        assertEquals("split index3 has wrong number of documents", max / 3, reader.numDocs());
        reader.close();
        h.getCore().getDirectoryFactory().release(directory);
        directory = null;
    } finally {
        // decrefs the searcher
        if (request != null)
            request.close();
        if (directory != null) {
            // perhaps an assert failed, release the directory
            h.getCore().getDirectoryFactory().release(directory);
        }
    }
}

@Test
public void testSplitByRouteKey() throws Exception {
    File indexDir = createTempDir().toFile();
    CompositeIdRouter r1 = new CompositeIdRouter();
    String splitKey = "sea-line!";
    String key2 = "soul-raising!";
    // murmur2 has a collision on the above two keys
    assertEquals(r1.keyHashRange(splitKey), r1.keyHashRange(key2));
    /*
    More strings with collisions on murmur2 for future reference:
    "Drava" "dessert spoon"
    "Bighorn" "pleasure lover"
    "attributable to" "second edition"
    "sea-line" "soul-raising"
    "lift direction" "testimony meeting"
     */
    for (int i = 0; i < 10; i++) {
        assertU(adoc("id", splitKey + i));
        assertU(adoc("id", key2 + i));
    }
    assertU(commit());
    assertJQ(req("q", "*:*"), "/response/numFound==20");
    DocRouter.Range splitKeyRange = r1.keyHashRange(splitKey);
    LocalSolrQueryRequest request = null;
    Directory directory = null;
    try {
        request = lrf.makeRequest("q", "dummy");
        SplitIndexCommand command = new SplitIndexCommand(request, Lists.newArrayList(indexDir.getAbsolutePath()), null, Lists.newArrayList(splitKeyRange), new CompositeIdRouter(), null, splitKey);
        new SolrIndexSplitter(command).split();
        directory = h.getCore().getDirectoryFactory().get(indexDir.getAbsolutePath(), DirectoryFactory.DirContext.DEFAULT, h.getCore().getSolrConfig().indexConfig.lockType);
        DirectoryReader reader = DirectoryReader.open(directory);
        assertEquals("split index has wrong number of documents", 10, reader.numDocs());
        reader.close();
        h.getCore().getDirectoryFactory().release(directory);
        directory = null;
    } finally {
        if (request != null) {
            request.close();
        }
        if (directory != null) {
            h.getCore().getDirectoryFactory().release(directory);
        }
    }
}

@Test
public void testExceededMaxTermLength() {
    // problematic field
    final String longFieldName = "cat";
    final String longFieldValue = TestUtil.randomSimpleString(random(), minTestTermLength, maxTestTermLength);
    //Dynamic field
    final String okayFieldName = TestUtil.randomSimpleString(random(), 1, 50) + "_sS";
    final String okayFieldValue = TestUtil.randomSimpleString(random(), minTestTermLength, maxTestTermLength);
    boolean includeOkayFields = random().nextBoolean();
    if (random().nextBoolean()) {
        //Use XML
        String doc;
        if (includeOkayFields) {
            doc = adoc("id", "1", longFieldName, longFieldValue, okayFieldName, okayFieldValue);
        } else {
            doc = adoc("id", "1", longFieldName, longFieldValue);
        }
        assertFailedU(doc);
    } else {
        //Use JSON
        try {
            if (includeOkayFields) {
                String jsonStr = "[{'id':'1','%s':'%s', '%s': '%s'}]";
                jsonStr = String.format(Locale.ROOT, jsonStr, longFieldName, longFieldValue, okayFieldName, okayFieldValue);
                updateJ(json(jsonStr), null);
            } else {
                String jsonStr = "[{'id':'1','%s':'%s'}]";
                jsonStr = String.format(Locale.ROOT, jsonStr, longFieldName, longFieldValue);
                updateJ(json(jsonStr), null);
            }
        } catch (Exception e) {
            //expected
            String msg = e.getCause().getMessage();
            assertTrue(msg.contains("one immense term in field=\"cat\""));
        }
    }
    assertU(commit());
    assertQ(req("q", "*:*"), "//*[@numFound='0']");
}

