        for (int i = 0; i < explicitThreshold; i++) {
            hll.addRaw(27 + i);
        }
        final byte[] bytes = hll.toBytes(schemaVersion);
        // assert output has correct byte length
        assertEquals(bytes.length, padding + (bytesPerWord * explicitThreshold));
