/**
 * Set cookies via interceptor
 * Change the request via an interceptor
 * Ensure cookies are actually set and that request is actually changed
 */
@Test
public void testInterceptors() {
    DebugServlet.clear();
    HttpClientUtil.addRequestInterceptor(changeRequestInterceptor);
    HttpClientUtil.addRequestInterceptor(cookieSettingRequestInterceptor);
    try (HttpSolrClient server = new HttpSolrClient(jetty.getBaseUrl().toString() + "/debug/foo")) {
        SolrQuery q = new SolrQuery("foo");
        q.setParam("a", "\u1234");
        try {
            server.query(q, random().nextBoolean() ? METHOD.POST : METHOD.GET);
        } catch (Throwable t) {
        }
        // Assert cookies from UseContextCallback
        assertNotNull(DebugServlet.cookies);
        boolean foundCookie = false;
        for (javax.servlet.http.Cookie cookie : DebugServlet.cookies) {
            if (cookieName.equals(cookie.getName()) && cookieValue.equals(cookie.getValue())) {
                foundCookie = true;
                break;
            }
        }
        assertTrue(foundCookie);
        // Assert request changes by ChangeRequestCallback
        assertEquals("\u1234", DebugServlet.parameters.get("a")[0]);
        assertEquals("\u4321", DebugServlet.parameters.get("b")[0]);
    } catch (IOException ex) {
        throw new RuntimeException(ex);
    } finally {
        HttpClientUtil.removeRequestInterceptor(changeRequestInterceptor);
        HttpClientUtil.removeRequestInterceptor(cookieSettingRequestInterceptor);
    }
}

@Test
public void testQueryString() throws Exception {
    try (HttpSolrClient client = new HttpSolrClient(jetty.getBaseUrl().toString() + "/debug/foo")) {
        // test without request query params
        DebugServlet.clear();
        client.setQueryParams(setOf("serverOnly"));
        UpdateRequest req = new UpdateRequest();
        setReqParamsOf(req, "serverOnly", "notServer");
        try {
            client.request(req);
        } catch (ParseException ignored) {
        }
        verifyServletState(client, req);
        // test without server query params
        DebugServlet.clear();
        client.setQueryParams(setOf());
        req = new UpdateRequest();
        req.setQueryParams(setOf("requestOnly"));
        setReqParamsOf(req, "requestOnly", "notRequest");
        try {
            client.request(req);
        } catch (ParseException ignored) {
        }
        verifyServletState(client, req);
        // test with both request and server query params
        DebugServlet.clear();
        req = new UpdateRequest();
        client.setQueryParams(setOf("serverOnly", "both"));
        req.setQueryParams(setOf("requestOnly", "both"));
        setReqParamsOf(req, "serverOnly", "requestOnly", "both", "neither");
        try {
            client.request(req);
        } catch (ParseException ignored) {
        }
        verifyServletState(client, req);
        // test with both request and server query params with single stream
        DebugServlet.clear();
        req = new UpdateRequest();
        req.add(new SolrInputDocument());
        client.setQueryParams(setOf("serverOnly", "both"));
        req.setQueryParams(setOf("requestOnly", "both"));
        setReqParamsOf(req, "serverOnly", "requestOnly", "both", "neither");
        try {
            client.request(req);
        } catch (ParseException ignored) {
        }
        // NOTE: single stream requests send all the params
        // as part of the query string.  So add "neither" to the request
        // so it passes the verification step.
        req.setQueryParams(setOf("requestOnly", "both", "neither"));
        verifyServletState(client, req);
    }
}

@Test
public void testWithChroot() throws IOException {
    boolean setOrList = random().nextBoolean();
    int numOfZKServers = TestUtil.nextInt(random(), 1, 5);
    boolean withChroot = random().nextBoolean();
    final String chroot = "/mychroot";
    StringBuilder sb = new StringBuilder();
    if (setOrList) {
        /*
        A LinkedHashSet is required here for testing, or we can't guarantee
        the order of entries in the final string.
       */
        hosts = new LinkedHashSet<>();
    } else {
        hosts = new ArrayList<>();
    }
    for (int i = 0; i < numOfZKServers; i++) {
        String ZKString = "host" + i + ":2181";
        hosts.add(ZKString);
        sb.append(ZKString);
        if (i < numOfZKServers - 1)
            sb.append(",");
    }
    String clientChroot = null;
    if (withChroot) {
        sb.append(chroot);
        clientChroot = "/mychroot";
    }
    try (CloudSolrClient client = new CloudSolrClient(hosts, clientChroot)) {
        assertEquals(sb.toString(), client.getZkHost());
    }
}

